function homeSelectors(p,e){const projects=state.projects.filter(x=>!x.isArchived).sort((a,b)=>a.sortOrder-b.sortOrder),episodes=state.episodes.filter(x=>x.projectId===p?.id&&!x.isArchived).sort((a,b)=>a.sortOrder-b.sortOrder);return `<section class="home-panel selector-panel"><div><p class="eyebrow">Project</p><h2>作品選択</h2><label>作品<select id="homeProject" onchange="homeSelectProject(this.value)">${projects.map(x=>`<option value="${x.id}" ${x.id===p?.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label></div><div><p class="eyebrow">Episode</p><h2>話数選択</h2><label>話数<select id="homeEpisode" onchange="selectContext(state.activeContext.projectId,this.value)">${episodes.map(x=>`<option value="${x.id}" ${x.id===e?.id?'selected':''}>${esc(x.numberLabel)}${x.subtitle?' / '+esc(x.subtitle):''}</option>`).join('')}</select></label></div></section>`}
