function homeStudioAction(id,title,desc,action,variant=''){
  const characterClass=`action-character${id.startsWith('Nova_')?' nova-action-character':''}`;
  return `<article class="atelier-action ${variant}" role="button" tabindex="0" onclick="${action}" onkeydown="if(event.key==='Enter'||event.key===' ')${action}">${homeCharacterImage(id,characterClass,title)}<div class="atelier-action-copy"><h3>${esc(title)}</h3><p>${esc(desc)}</p></div><button class="secondary" onclick="event.stopPropagation();${action}">開く</button></article>`;
}
function openHomeStudioPreview(title,description){
  modal(`<h2>${esc(title)}</h2><p>${esc(description)}</p><p class="meta">このStudioの入口をホームに用意しました。制作機能は今後ここから接続します。</p><button class="primary-action" onclick="closeModal()">ホームへ戻る</button>`);
}
const HOME_STUDIOS=[
  ['Tia_Chibi_Reading.png','Story Studio','物語・構成・脚本をつくる',"setView('story-studio')"],
  ['Nova_Sparkle.png','Prompt Studio','映像生成プロンプトを整える',"setView('prompt-studio')"],
  ['Nova_Joy.png','Music Studio','音楽と音の制作へ進む',"openApp('musicStudio')"],
  ['Tia_Chibi_Smile.png','Character Studio','キャラクター設定と差分を管理する',"setView('character-studio')"],
  ['Tia_Chibi_Welcome.png','Background Studio','背景・場所・時間帯を整える',"setView('background-studio')"],
  ['Nova_Thinking.png','Voice Studio','セリフと音声を管理する',"setView('voice-studio')"],
  ['Tia_Chibi_HappyJump.png','Video Studio','動画素材と編集をまとめる',"setView('video-studio')"],
  ['Tia_Chibi_Peace.png','Comic Studio','漫画・制作日誌画像をつくる',"setView('comic-studio')"],
  ['Nova_Cool.png','LINE・SNS Studio','スタンプ・告知画像・投稿素材をつくる',"setView('line-sns-studio')"],
  ['Tia_Chibi_Wink_Heart.png','Web Studio','サイト・作品ページをつくる',"setView('web-studio')"]
];
const HOME_MANAGEMENT=[
  ['📚','Story Archive','物語の記憶と設定カードを開く','openStoryArchive()'],
  ['📊','Production Dashboard','作品と話数の進行を確認する','openProductionDashboard()'],
  ['🌌','Universe','作品世界のつながりを見る',"setView('universe')"]
];
function homeCardSection(label,title,items,className){
  return `<section class="atelier-card-section ${className}" aria-labelledby="${className}-title"><div class="atelier-section-heading"><p class="eyebrow">${esc(label)}</p><h2 id="${className}-title">${esc(title)}</h2></div><div class="atelier-actions">${items.map(item=>homeStudioAction(...item)).join('')}</div></section>`;
}
function homeManagementSection(){
  return `<section class="atelier-management-section" aria-labelledby="management-section-title"><div class="atelier-section-heading"><p class="eyebrow">Management & Archive</p><h2 id="management-section-title">管理・保管</h2></div><nav class="atelier-management-links" aria-label="管理・保管メニュー">${HOME_MANAGEMENT.map(([icon,title,description,action])=>`<button type="button" onclick="${action}"><span class="management-link-icon" aria-hidden="true">${icon}</span><span class="management-link-copy"><b>${esc(title)}</b><small>${esc(description)}</small></span><span class="management-link-arrow" aria-hidden="true">→</span></button>`).join('')}</nav></section>`;
}
function homeFeaturedEpisode(p,e){
  return state.episodes.find(x=>x.projectId===p?.id&&x.numberLabel==='第0話')||e;
}
function openFeaturedEpisode(){
  const p=currentProject(),e=homeFeaturedEpisode(p,currentEpisode());
  if(p?.id&&e?.id)selectContext(p.id,e.id);
  openLastLocation();
}
function homeProductionStatus(p,e){
  const featured=homeFeaturedEpisode(p,e);
  return {project:p?.title||'作品未選択',episode:featured?.numberLabel||e?.numberLabel||'話数未選択',status:featured?.productionStatus||featured?.production?.status||p?.productionStatus||featured?.status||p?.status||'制作中'};
}
function homeRecentSummary(){
  const recent=homeRecentItems().slice(0,3);
  return recent.length?recent.map(r=>`<button class="atelier-mini-row" onclick="openHomeRecent('${r.id||''}','${r.collection||''}','${r.item?.id||''}')"><b>${esc(r.title)}</b><small>${esc(TYPE_LABELS[r.type]||typeLabel(r.type)||r.type||'項目')} / ${esc(r.updatedAt||'')}</small></button>`).join(''):'<p class="atelier-empty">最近開いた作品はまだありません。</p>';
}
function homeTaskSummary(){
  const tasks=typeof tasksForProject==='function'?tasksForProject().filter(t=>!t.completed).slice(0,3):[];
  return tasks.length?tasks.map(t=>`<div class="atelier-mini-row static"><b>${esc(t.title||t.body||'タスク')}</b><small>${esc(t.priority||'中')} / ${esc(t.dueDate||'期限なし')}</small></div>`).join(''):'<p class="atelier-empty">今日やることはありません。</p>';
}
function homeSaveSummary(){
  const auto=state.settings?.autoSave?'自動保存オン':'自動保存オフ';
  const saved=state.lastSavedAt||state.updatedAt||'ローカル保存';
  return `<div class="atelier-mini-row static"><b>${esc(auto)}</b><small>${esc(saved)}</small></div>`;
}
function homeBackupSummary(){
  const exported=state.backupStatus?.lastExportedAt||'書き出し履歴なし';
  const imported=state.backupStatus?.lastImportedAt||'読み込み履歴なし';
  return `<button class="atelier-mini-row" onclick="setView('backup')"><b>バックアップ</b><small>書き出し：${esc(exported)} / 読み込み：${esc(imported)}</small></button>`;
}
function homeFooterPanel(title,body,action=''){
  return `<section class="atelier-footer-panel"><div class="section-head"><h2>${esc(title)}</h2>${action}</div>${body}</section>`;
}
function homeHeroSection(){
  return `<section class="atelier-hero" aria-label="Nova Studio Hero"><div class="atelier-hero-media"><img src="./assets/images/home/nova-studio-home-hero-20260804.png" alt="Nova Studioの幻想世界を描いたHeroバナー" width="1920" height="480" loading="eager" decoding="async"></div></section>`;
}
homeView=function(){
  const p=currentProject(),e=currentEpisode(),info=homeProductionStatus(p,e);
  return `<main class="atelier-home home-only" aria-label="Nova Studio">${homeHeroSection()}<section class="atelier-continue" role="button" tabindex="0" onclick="openFeaturedEpisode()" onkeydown="if(event.key==='Enter'||event.key===' ')openFeaturedEpisode()"><div class="atelier-continue-heading"><p class="eyebrow">Continue</p><h2>制作を続ける</h2></div><div class="atelier-continue-side"><div class="home-gemini-actions" aria-label="AI連携"></div>${homeImage('Tia_Chibi_Wink_Heart.png','tia-thinking','ハートを作るティア')}</div><dl><div><dt>作品名</dt><dd>${esc(info.project)}</dd></div><div><dt>話数</dt><dd>${esc(info.episode)}</dd></div><div><dt>制作状況</dt><dd>${esc(info.status)}</dd></div></dl></section>${homeCardSection('Creative Studios','Studios',HOME_STUDIOS,'studio-section')}${homeManagementSection()}</main>`;
};
render=function(){
  const v=(location.hash||'#home').slice(1)||HOME_ROUTE;
  document.body.classList.toggle('is-home-route',v===HOME_ROUTE);
  document.body.classList.toggle('is-management-route',v!==HOME_ROUTE);
  if(v===HOME_ROUTE){
    document.querySelector('#app').innerHTML=homeView();
    return;
  }
  nova125RenderBase();
};
render();

/* Version 0.3.0 Story Archive image material manager completion */
const ARCHIVE_IMAGE_TYPES_030=['立ち絵','表情','背景','小物','Vidu','参考','キャラクター','アイテム','エフェクト','ロゴ','UI','その他'];
const ARCHIVE_IMAGE_ANGLES_030=['正面','横','後ろ','斜め','左側面','右側面','斜め前','斜め後ろ','俯瞰','煽り','真上','その他'];
const archive030NormalizeCardBase=normalizeStoryArchiveCard;
normalizeStoryArchiveCard=function(card={}){const c=archive030NormalizeCardBase(card);c.representativeImageId=card.representativeImageId||card.coverImageId||'';c.images=(Array.isArray(c.images)?c.images:[]).map((img,i)=>normalizeArchiveImage({...img,sortOrder:Number(img.sortOrder||i+1)},c));return c};
function archive030OptionList(values,selected){return values.map(v=>`<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(v)}</option>`).join('')}
function archiveRepresentativeImage(card){card=normalizeStoryArchiveCard(card);const imgs=card.images||[];return imgs.find(i=>i.id===card.representativeImageId)||imgs.find(i=>i.isOfficial||i.state==='正式採用')||imgs.find(i=>i.isViduReference)||imgs[0]||null}
function setArchiveRepresentativeImage(cardId,imgId){const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId));if(!card||!card.images?.some(i=>i.id===imgId))return;card.representativeImageId=imgId;card.updatedAt=now();saveNormalizedArchiveCard(card);saveState(true);openStoryArchiveDetail(cardId);toast('代表画像を変更しました')}
function archiveRepresentativeHero(card){const img=archiveRepresentativeImage(card);return `<section class="archive-detail-hero"><div class="archive-hero-copy"><p class="eyebrow">代表画像</p><p class="meta">ギャラリー内の「代表にする」でワンクリック変更できます。</p></div><div class="archive-representative" ${img?`onclick="openArchiveImageDetail('${card.id}','${img.id}')"`:''}>${img?archiveThumbWithLabels(img):'<div class="archive-thumb-empty">画像なし</div>'}</div></section>`}
function archiveImageMetaGrid(img){return `<dl class="archive-image-meta"><dt>画像名</dt><dd>${esc(img.name||'画像資料')}</dd><dt>種類</dt><dd>${esc(img.materialType||'未設定')}</dd><dt>角度</dt><dd>${esc(img.angle||'未設定')}</dd><dt>正式採用</dt><dd>${img.isOfficial?'ON':'OFF'}</dd><dt>Vidu参照画像</dt><dd>${img.isViduReference?'ON':'OFF'}</dd><dt>状態</dt><dd>${esc(img.state||'未設定')}</dd></dl>`}
function archiveImageCard(card,img){const isRep=normalizeStoryArchiveCard(card).representativeImageId===img.id;return `<article class="archive-image-card archive-image-row ${isRep?'is-representative':''}" draggable="true" ondragstart="dragArchiveImage(event,'${card.id}','${img.id}')" ondragover="event.preventDefault()" ondrop="dropArchiveImage(event,'${card.id}','${img.id}')" onclick="openArchiveImageDetail('${card.id}','${img.id}')"><label class="archive-select" onclick="event.stopPropagation()"><input type="checkbox" value="${esc(img.id)}" data-archive-image-select="${esc(card.id)}">選択</label>${archiveThumbWithLabels(img)}<div><b>${esc(img.name||'画像資料')}</b>${archiveImageMetaGrid(img)}<small>${archiveImageBadges(img)}</small><small>${esc(img.fileName||'')} ${img.storageLocation?` / ${esc(img.storageLocation)}`:''}</small></div><div class="archive-card-actions"><button class="primary-action" onclick="event.stopPropagation();setArchiveRepresentativeImage('${card.id}','${img.id}')">${isRep?'代表画像':'代表にする'}</button><button onclick="event.stopPropagation();editArchiveImage('${card.id}','${img.id}')">編集</button><button class="danger" onclick="event.stopPropagation();deleteArchiveImage('${card.id}','${img.id}')">削除</button></div></article>`}
let archiveDraggedImageId='';function dragArchiveImage(e,cardId,imgId){archiveDraggedImageId=imgId;e.dataTransfer?.setData('text/plain',imgId)}
function dropArchiveImage(e,cardId,targetId){e.preventDefault();const fromId=e.dataTransfer?.getData('text/plain')||archiveDraggedImageId;if(!fromId||fromId===targetId)return;const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId)),imgs=[...(card.images||[])],from=imgs.findIndex(i=>i.id===fromId),to=imgs.findIndex(i=>i.id===targetId);if(from<0||to<0)return;const [moved]=imgs.splice(from,1);imgs.splice(to,0,moved);card.images=imgs.map((img,i)=>({...img,sortOrder:i+1,updatedAt:img.id===fromId?now():img.updatedAt}));card.updatedAt=now();saveNormalizedArchiveCard(card);saveState(true);openStoryArchiveDetail(cardId);toast('画像の順番を変更しました')}
archiveImageControls=function(card,mode='all'){return `<div class="archive-image-toolbar enhanced"><input id="archiveImageSearch_${card.id}" placeholder="画像名・ファイル名・タグ・説明で検索" oninput="filterArchiveImages('${card.id}','${mode}')"><select id="archiveImageSort_${card.id}" onchange="filterArchiveImages('${card.id}','${mode}')">${ARCHIVE_IMAGE_SORTS.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><select id="archiveImageType_${card.id}" onchange="filterArchiveImages('${card.id}','${mode}')"><option value="">種類すべて</option>${[...new Set([...(card.images||[]).map(i=>i.materialType).filter(Boolean),...ARCHIVE_IMAGE_TYPES_030])].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="archiveImageAngle_${card.id}" onchange="filterArchiveImages('${card.id}','${mode}')"><option value="">角度すべて</option>${[...new Set([...(card.images||[]).map(i=>i.angle).filter(Boolean),...ARCHIVE_IMAGE_ANGLES_030])].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="archiveImageState_${card.id}" onchange="filterArchiveImages('${card.id}','${mode}')"><option value="">状態すべて</option>${[...new Set((card.images||[]).map(i=>i.state).filter(Boolean))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="archiveImageSetFilter_${card.id}" onchange="filterArchiveImages('${card.id}','${mode}')"><option value="">画像セットすべて</option>${(card.imageSets||[]).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></div>`}
function archiveImageMatches030(img,q,type,angle,stateVal){const hay=[img.name,img.fileName,img.materialType,img.angle,img.state,img.description,img.storageLocation,(img.tags||[]).join(' ')].join(' ').toLowerCase();return (!q||hay.includes(String(q).toLowerCase()))&&(!type||img.materialType===type)&&(!angle||img.angle===angle)&&(!stateVal||img.state===stateVal)}
archiveVisibleImagesEnhanced=function(card,mode='all'){let imgs=[...(card.images||[])];if(mode==='official')imgs=imgs.filter(i=>i.isOfficial||i.state==='正式採用');if(mode==='vidu')imgs=imgs.filter(i=>i.isViduReference);if(mode==='old')imgs=imgs.filter(i=>['旧案','旧デザイン'].includes(i.state)||['旧案','旧デザイン'].includes(i.materialType));if(mode==='rejected')imgs=imgs.filter(i=>i.state==='没案'||i.materialType==='没案');const q=$(`#archiveImageSearch_${card.id}`)?.value||'',type=$(`#archiveImageType_${card.id}`)?.value||'',angle=$(`#archiveImageAngle_${card.id}`)?.value||'',stateVal=$(`#archiveImageState_${card.id}`)?.value||'',setId=$(`#archiveImageSetFilter_${card.id}`)?.value||'',sort=$(`#archiveImageSort_${card.id}`)?.value||'manual';imgs=imgs.filter(i=>archiveImageMatches030(i,q,type,angle,stateVal)&&(setId?!setId||i.imageSetId===setId||card.imageSets?.find(s=>s.id===setId)?.imageIds?.includes(i.id):true));const key=sort==='name'?'name':sort;imgs.sort((a,b)=>sort==='manual'?(+a.sortOrder||0)-(+b.sortOrder||0):String(a[key]||'').localeCompare(String(b[key]||''),'ja'));return imgs}
function archiveDetailGallerySection(card,mode='all'){return `<section class="archive-gallery-panel"><div class="section-head"><div><h3>画像ギャラリー</h3><p class="meta">画像クリックで中央拡大表示。ドラッグで並び替え、代表画像ボタンでワンクリック変更できます。</p></div><div class="archive-image-actions"><button class="primary-action" onclick="editArchiveImage('${card.id}')">画像追加</button><button class="secondary" onclick="editArchiveImageSet('${card.id}')">画像セット管理</button></div></div><div class="gallery-tabs">${archiveGalleryTabs(card.id)}<button class="vidu-one-tap" onclick="openArchiveViduReferences()">全カードのVidu参照</button></div>${mode==='set'?'':archiveImageControls(card,mode)}<div class="archive-bulk-bar"><button class="secondary" onclick="document.querySelectorAll('[data-archive-image-select=&quot;${card.id}&quot;]').forEach(x=>x.checked=true)">全選択</button><button class="secondary" onclick="document.querySelectorAll('[data-archive-image-select=&quot;${card.id}&quot;]').forEach(x=>x.checked=false)">選択解除</button><button class="primary-action" onclick="openArchiveBulkEdit('${card.id}')">選択画像を一括編集</button></div><div id="archiveImageResults_${card.id}">${['type','angle','state'].includes(mode)?archiveGroupedGallery(card,mode):archiveImageGallery(card,mode)}</div>${archiveImageDropZone(card.id)}</section>`}
openStoryArchiveDetail=function(id,mode='all'){const card=normalizeStoryArchiveCardV1(getStoryArchiveCard(id));if(!card)return;modal(`<article class="archive-detail"><h2>${esc(card.title)}</h2>${archiveRepresentativeHero(card)}${archiveDetailGallerySection(card,mode)}${archiveDetailBasicSection(card)}<section><h3>関連カード</h3>${archiveRelatedLinks(card)}</section>${archiveManagementDetails(card)}<button onclick="editStoryArchiveCard('${id}')">カード編集</button><button class="secondary" onclick="closeModal()">閉じる</button></article>`)};
const archive030OldEditArchiveImage=editArchiveImage;
editArchiveImage=function(cardId,imgId=''){archive030OldEditArchiveImage(cardId,imgId);setTimeout(()=>{const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId)),img=normalizeArchiveImage(imgId?card.images.find(i=>i.id===imgId):{},card),type=$('#imgType'),angle=$('#imgAngle');if(type)type.innerHTML=archive030OptionList([...new Set([...ARCHIVE_IMAGE_TYPES_030,...ARCHIVE_IMAGE_TYPES_PRODUCTION])],img.materialType);if(angle)angle.innerHTML=archive030OptionList([...new Set([...ARCHIVE_IMAGE_ANGLES_030,...ARCHIVE_ANGLES_PRODUCTION])],img.angle);},0)};
function archive030LightboxClose(cardId){document.body.classList.remove('archive-lightbox-open');openStoryArchiveDetail(cardId)}
openArchiveImageDetail=function(cardId,imgId){const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId)),imgs=[...(card.images||[])].sort((a,b)=>(+a.sortOrder||0)-(+b.sortOrder||0));let idx=imgs.findIndex(i=>i.id===imgId);if(idx<0)return;const img=imgs[idx],prev=imgs[(idx-1+imgs.length)%imgs.length],next=imgs[(idx+1)%imgs.length];modal(`<div class="archive-lightbox archive-lightbox-030" ontouchstart="archiveLightboxTouchStart(event)" ontouchend="archiveLightboxTouchEnd(event,'${cardId}','${prev?.id||''}','${next?.id||''}')"><button class="archive-lightbox-close" aria-label="閉じる" onclick="archive030LightboxClose('${cardId}')">×</button><div class="section-head"><div><h2>${esc(img.name)}</h2><p class="meta">${idx+1} / ${imgs.length}　ESCでも閉じられます</p></div></div><div class="archive-lightbox-stage"><button class="archive-lightbox-arrow" ${imgs.length<2?'disabled':''} onclick="openArchiveImageDetail('${cardId}','${prev.id}')">←</button><div class="archive-zoom-target" id="archiveZoomTarget" style="--zoom:1">${archiveThumbWithLabels(img)}</div><button class="archive-lightbox-arrow" ${imgs.length<2?'disabled':''} onclick="openArchiveImageDetail('${cardId}','${next.id}')">→</button></div><div class="archive-image-actions"><button onclick="archiveZoom(-.25)">縮小</button><button onclick="archiveZoom(.25)">拡大</button><button onclick="archiveZoom(0,true)">等倍</button><button class="primary-action" onclick="setArchiveRepresentativeImage('${cardId}','${imgId}')">代表にする</button><button onclick="editArchiveImage('${cardId}','${imgId}')">編集</button></div><section><h3>画像情報</h3>${archiveImageMetaGrid(img)}<p><b>保存場所：</b>${esc(img.storageLocation||'未設定')}<br><b>ファイル名：</b>${esc(img.fileName||'未設定')}<br><b>タグ：</b>${esc((img.tags||[]).join(', ')||'なし')}</p><p>${esc(img.description||'説明は未入力です。')}</p></section></div>`);document.body.classList.add('archive-lightbox-open')};
const archive030OldCloseModal=closeModal;closeModal=function(){document.body.classList.remove('archive-lightbox-open');archive030OldCloseModal()};
storyArchiveView=function(){memorySyncInitConstants?.();const cards=storyArchiveCards().map(normalizeStoryArchiveCardV1),q=($('#archiveSearch')?.value||'').toLowerCase();const filtered=q?cards.filter(c=>[c.title,c.category,c.status,c.updatedAt,c.timelineAt,(c.tags||[]).join(' '),(c.images||[]).map(i=>[i.name,i.fileName,i.materialType,i.angle,i.description,(i.tags||[]).join(' ')].join(' ')).join(' '),archiveRelatedIds(c).map(id=>getStoryArchiveCard(id)?.title||'').join(' ')].join(' ').toLowerCase().includes(q)):cards;const byCat=Object.groupBy?Object.groupBy(filtered,c=>c.category||'未分類'):filtered.reduce((a,c)=>((a[c.category||'未分類']=a[c.category||'未分類']||[]).push(c),a),{});return `<section class="hero archive-hero"><h1>Story Archive</h1><p>設定資料集の代わりに毎日使う、画像資料中心のカード一覧です。 <span class="ver">Version 0.3.0</span></p><div class="archive-hero-actions"><button class="primary-action" onclick="editStoryArchiveCard()">＋カード作成</button><button class="secondary" onclick="openMemorySync()">Memory Sync</button><button class="secondary vidu-one-tap" onclick="openArchiveViduReferences()">Vidu参照画像だけ表示（${archiveViduReferenceImages().length}）</button></div><input id="archiveSearch" placeholder="タイトル・画像名・ファイル名・カテゴリ・状態・タグ・関連カードを検索" value="${esc($('#archiveSearch')?.value||'')}" oninput="render()"></section><section><div class="archive-category-grid image-first-archive-grid">${archiveListCategories(filtered).map(cat=>`<article class="archive-category image-first-category"><h3>${esc(cat)} <span class="meta">${(byCat[cat]||[]).length}件</span></h3>${(byCat[cat]||[]).map(c=>`<article class="archive-card image-first-card" role="button" tabindex="0" onclick="openStoryArchiveDetail('${c.id}')" onkeydown="if(event.key==='Enter'||event.key===' ')openStoryArchiveDetail('${c.id}')">${archiveCardListImage(c)}${archiveCardListMeta(c)}<div class="archive-card-actions"><button onclick="event.stopPropagation();editStoryArchiveCard('${c.id}')">編集</button><button class="danger" onclick="event.stopPropagation();deleteStoryArchiveCard('${c.id}')">削除</button></div></article>`).join('')||'<p class="empty-note">カードなし</p>'}</article>`).join('')}</div></section><section><h2>Memory Sync履歴</h2>${memorySyncHistoryRows()}</section>`};
render();

/* Final layout separation: home and management are exclusive views. */
const NOVA_STUDIO_HERO_PLACEHOLDER='./assets/images/home/nova-studio-home-hero-20260804.png';
const NOVA_STUDIO_HERO_CONFIGS=[
  {studioKey:'story',route:'story-studio',title:'Story Studio',category:'STORY & SCRIPT',subtitle:'物語・構成・脚本をひとつの制作導線で組み立てます。',badge:'Worldbuilding',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'prompt',route:'prompt-studio',title:'Prompt Studio',category:'PROMPT DESIGN',subtitle:'映像生成の発想と言葉を、再利用しやすい形へ整えます。',badge:'Prompt Craft',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'music',route:'music-studio',title:'Music Studio',category:'MUSIC PRODUCTION',subtitle:'音楽プロジェクトを安全に作成・保存・管理します。',badge:'MIDI / Logic Pro',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'character',route:'character-studio',title:'Character Studio',category:'CHARACTER DESIGN',subtitle:'キャラクター設定・表情差分・参照資料を育てます。',badge:'Design Sheet',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'background',route:'background-studio',title:'Background Studio',category:'BACKGROUND ART',subtitle:'背景・場所・時間帯と、作品世界の色設計を整えます。',badge:'Environment',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'voice',route:'voice-studio',title:'Voice Studio',category:'VOICE PRODUCTION',subtitle:'セリフと音声収録の素材・状態をまとめて管理します。',badge:'Voice & Wave',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'video',route:'video-studio',title:'Video Studio',category:'VIDEO EDITING',subtitle:'動画素材・フレーム・編集工程をひとつにまとめます。',badge:'Timeline',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'comic',route:'comic-studio',title:'Comic Studio',category:'COMIC PRODUCTION',subtitle:'コマ・吹き出し・漫画原稿の制作を組み立てます。',badge:'Panels & Ink',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'line-sns',route:'line-sns-studio',title:'LINE / SNS Studio',category:'SOCIAL CONTENT',subtitle:'スタンプ・告知画像・投稿素材を媒体ごとに整えます。',badge:'Share & Post',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'},
  {studioKey:'web',route:'web-studio',title:'Web Studio',category:'WEB DESIGN',subtitle:'サイト設計と作品ページの見せ方を組み立てます。',badge:'Layout & Publish',image:NOVA_STUDIO_HERO_PLACEHOLDER,status:'placeholder'}
];
const NOVA_STUDIO_HERO_BY_ROUTE=new Map(NOVA_STUDIO_HERO_CONFIGS.map(config=>[config.route,config]));
function studioHeroConfigForRoute(route){
  const exact=NOVA_STUDIO_HERO_BY_ROUTE.get(route);
  if(exact)return exact;
  return String(route||'').startsWith('music-studio/')?NOVA_STUDIO_HERO_BY_ROUTE.get('music-studio'):null;
}
function renderStudioHero(config){
  return `<section class="atelier-hero studio-route-hero" data-studio-key="${esc(config.studioKey)}" data-hero-image-status="${esc(config.status)}" aria-labelledby="studio-hero-title-${esc(config.studioKey)}"><div class="atelier-hero-media"><img src="${esc(config.image)}" alt="${esc(config.title)}のHeroイラスト（共通フォーマット準備画像）" width="1920" height="480" loading="eager" decoding="async"></div><div class="studio-hero-copy"><p class="studio-hero-category">${esc(config.category)}</p><h1 id="studio-hero-title-${esc(config.studioKey)}">${esc(config.title)}</h1><p>${esc(config.subtitle)}</p></div><span class="studio-hero-badge">${esc(config.badge)}</span></section>`;
}
function novaStudioPlaceholderView(config){
  return `<section class="studio-stage-panel" aria-labelledby="studio-stage-title-${esc(config.studioKey)}"><p class="eyebrow">Studio foundation</p><h2 id="studio-stage-title-${esc(config.studioKey)}">${esc(config.title)} 制作入口</h2><p>${esc(config.subtitle)}</p><p class="meta">既存機能と保存データを維持したまま、正式イラストと制作機能を接続できる共通Hero土台を準備しています。</p></section>`;
}
function isMusicEditorStudioRoute(route){
  return route==='music-studio/midi-composer'||String(route||'').startsWith('music-studio/midi-editor/');
}
function novaRenderStudioRoute(route,mainContent){
  const config=studioHeroConfigForRoute(route);
  if(!config)return false;
  document.body.classList.remove('is-home-route','is-management-route','is-universe-route','is-unified-route','nav-open');
  document.body.classList.add('is-studio-route');
  if(isMusicEditorStudioRoute(route)){
    delete document.body.dataset.homeBackground;
    document.body.style.removeProperty('--home-background-image');
    document.querySelector('#app').innerHTML=`${mainContent}<div id="toast"></div>`;
    return true;
  }
  document.body.dataset.homeBackground='fantasyAtelier';
  document.body.style.setProperty('--home-background-image',"url('./fantasy_atelier_background.png')");
  document.querySelector('#app').innerHTML=`<main class="nova-studio-route-main" data-nova-studio-route="${esc(route)}" data-studio-key="${esc(config.studioKey)}" aria-label="${esc(config.title)}">${renderStudioHero(config)}<section class="nova-studio-route-content">${mainContent}</section></main><div id="toast"></div>`;
  return true;
}
function novaRenderHomeOnly(){
  document.body.classList.add('is-home-route');
  document.body.classList.remove('is-management-route','is-universe-route','is-unified-route','is-studio-route','nav-open');
  document.querySelector('#app').innerHTML=homeView();
}
const NOVA_UNIFIED_ROUTES=new Set(['storyArchive','productionDashboard','backup','settings']);
function novaRenderUnifiedRoute(route,mainContent){
  document.body.classList.remove('is-home-route','is-management-route','is-universe-route','is-studio-route','nav-open');
  document.body.classList.add('is-unified-route');
  document.body.dataset.homeBackground='fantasyAtelier';
  document.body.style.setProperty('--home-background-image',"url('./fantasy_atelier_background.png')");
  document.querySelector('#app').innerHTML=`<main class="nova-unified-main nova-unified-page" data-nova-unified-route="${route}" aria-label="Nova Studio">${homeHeroSection()}<section class="nova-unified-content">${mainContent}</section></main><div id="toast"></div>`;
}
function novaReturnHome(){setView(HOME_ROUTE)}
function managementNavSection(title,items,open=false){
  return `<details class="management-nav-section" ${open?'open':''}><summary>${esc(title)}</summary>${items.map(item=>`<button onclick="${item.action}">${esc(item.label)}</button>`).join('')}</details>`;
}
function managementNav(){
  return `<nav class="management-nav" aria-label="管理メニュー"><button class="management-home-button" onclick="novaReturnHome()">ホーム</button>${managementNavSection('制作',[{label:'作品',action:"setView('projects')"},{label:'話数',action:"setView('episodes')"},{label:'シーン',action:"setView('scenes')"},{label:'Story Archive',action:'openStoryArchive()'},{label:'Production Dashboard',action:'openProductionDashboard()'},{label:'Prompt Studio',action:"openApp('promptStudio')"},{label:'Music Studio',action:"openApp('musicStudio')"}],true)}${managementNavSection('世界設定',[{label:'キャラクター',action:"setView('characters')"},{label:'世界観',action:"setView('worlds')"},{label:'用語',action:"setView('terms')"},{label:'年表',action:"setView('timelines')"},{label:'Universe',action:"setView('universe')"}])}${managementNavSection('管理',[{label:'今日やること',action:"setView('tasks')"},{label:'進捗',action:"setView('progress')"},{label:'アイデア',action:"setView('ideas')"},{label:'検索',action:"setView('search')"},{label:'変更履歴',action:"setView('history')"}])}${managementNavSection('設定',[{label:'バックアップ',action:"setView('backup')"},{label:'設定',action:"setView('settings')"}])}</nav>`;
}
shell=function(main){
  const p=currentProject(),e=currentEpisode();
  const route=(location.hash||'#home').slice(1);
  if(route==='universe'){
    document.querySelector('#app').innerHTML=`<main class="universe-main">${homeHeroSection()}<section class="atelier-card-section universe-panel">${main}</section></main><div id="toast"></div>`;
    return;
  }
  document.querySelector('#app').innerHTML=`<header class="management-header"><button class="brand return-home" onclick="novaReturnHome()"><b>Nova Studioへ戻る</b><small>アトリエホーム</small></button><button class="hamburger" onclick="document.body.classList.toggle('nav-open')" aria-label="メニューを開閉">☰</button><button onclick="showContext()">作品：${esc(p?.title||'未選択')}</button><button onclick="showContext()">話数：${esc(e?.numberLabel||'未選択')}</button><input id="globalSearch" aria-label="全体検索" placeholder="全体検索" oninput="searchAll(this.value)"><button onclick="setView('consult')">ノヴァに相談</button><button onclick="setView('backup')">バックアップ</button><button onclick="setView('settings')">設定</button><span id="saveStatus">保存しました</span></header><div class="management-layout">${managementNav()}<main class="management-main">${productionFlowNav?productionFlowNav():''}${main}</main><aside class="management-side">${side()}</aside></div><div class="mobile-nav-backdrop" onclick="document.body.classList.remove('nav-open')"></div><div class="bottom management-bottom"><button onclick="novaReturnHome()">ホーム</button><button onclick="openStoryArchive()">Archive</button><button onclick="openProductionDashboard()">Dashboard</button><button onclick="setView('search')">検索</button><button onclick="setView('settings')">設定</button></div><div id="toast"></div>`;
};
function managementViewForRoute(v){
  const views={apps:appsView,cards:cardsView,projects:projectsView,episodes:episodesView,history:historyView,settings:settingsView,backup:backupView,consult:consultView,search:searchView,universe:universeView,tasks:tasksView,progress:progressView,projectDashboard:projectDashboardView,importCenter:importCenterView,storyArchive:storyArchiveView,scenes:()=>storyCollectionView('scenes'),characters:()=>storyCollectionView('characters'),worlds:()=>storyCollectionView('worlds'),terms:()=>storyCollectionView('terms'),timelines:()=>storyCollectionView('timelines'),ideas:()=>storyCollectionView('ideas')};
  return (views[v]||appsView)();
}
render=function(){
  ensureV06?.();
  const v=(location.hash||'#home').slice(1)||HOME_ROUTE;
  document.body.classList.remove('is-home-route','is-management-route','is-universe-route','is-unified-route','is-studio-route','nav-open');
  if(v===HOME_ROUTE){
    novaRenderHomeOnly();
    return;
  }
  recordLastLocation?.({view:v});
  if(NOVA_UNIFIED_ROUTES.has(v)){
    novaRenderUnifiedRoute(v,managementViewForRoute(v));
    return;
  }
  if(studioHeroConfigForRoute(v)){
    novaRenderStudioRoute(v,managementViewForRoute(v));
    return;
  }
  document.body.classList.add('is-management-route');
  document.body.classList.toggle('is-universe-route',v==='universe');
  shell(managementViewForRoute(v));
};
render();

/* Final route aliases for production app entries inside the management shell. */
function appWorkspaceView(appId){
  const a=state.apps.find(x=>x.id===appId)||{name:appId,subtitle:'制作アプリ',description:'URL未登録の制作アプリです。',url:''};
  return `<section class="hero"><p class="eyebrow">Production App</p><h1>${esc(a.name||a.subtitle||appId)}</h1><p>${esc(a.description||a.subtitle||'')}</p><p class="meta">URL：${a.url?esc(a.url):'未登録'} / 最終閲覧：${esc(a.lastOpenedAt||'なし')}</p><button class="primary-action" onclick="editApp('${esc(appId)}')">URL登録・設定</button>${a.url?`<button class="secondary" onclick="window.open('${esc(a.url)}','_blank','noopener')">登録URLを開く</button>`:''}</section>`;
}
const novaFinalOpenAppBase=openApp;
openApp=function(appId,urlOverride){
  if(appId==='musicStudio'&&!urlOverride)return setView('music-studio');
  if(appId==='promptStudio'&&!urlOverride)return setView('prompt-studio');
  if(appId==='voiceStudio'&&!urlOverride)return setView('voice-studio');
  return novaFinalOpenAppBase(appId,urlOverride);
};
const novaFinalOpenProductionDashboardBase=typeof openProductionDashboard==='function'?openProductionDashboard:null;
openProductionDashboard=function(){
  const app=state.apps.find(a=>a.id==='productionDashboard');
  if(app?.url&&novaFinalOpenProductionDashboardBase)return novaFinalOpenProductionDashboardBase();
  setView('productionDashboard');
};
const novaFinalManagementViewForRouteBase=managementViewForRoute;
function musicStudioHostRouteView(route,studio=window.MusicStudio){
  if(route!=='music-studio'&&!String(route||'').startsWith('music-studio/'))return null;
  if(studio&&typeof studio.renderRoute==='function')return studio.renderRoute(route);
  return '<main class="music-studio-shell" data-music-studio-loading="true" aria-busy="true"><p class="music-empty">Music Studioを読み込んでいます…</p></main>';
}
managementViewForRoute=function(v){
  const musicStudioView=musicStudioHostRouteView(v);
  if(musicStudioView!==null)return musicStudioView;
  if(v==='productionDashboard')return projectDashboardView();
  if(v==='prompt-studio'||v==='promptStudio')return appWorkspaceView('promptStudio');
  if(v==='musicStudio')return appWorkspaceView('musicStudio');
  if(v==='story-studio')return storyCollectionView('scenes');
  if(v==='character-studio')return storyCollectionView('characters');
  if(v==='background-studio')return storyCollectionView('worlds');
  if(v==='voice-studio')return appWorkspaceView('voiceStudio');
  if(['video-studio','comic-studio','line-sns-studio','web-studio'].includes(v))return novaStudioPlaceholderView(studioHeroConfigForRoute(v));
  return novaFinalManagementViewForRouteBase(v);
};
render();

/* Story Archive 1.3 image-first production reference board */
const ARCHIVE_UI_TYPES=['キャラクター','世界観','場所','アイテム','用語','その他'];
let archiveLightboxContext=null;
function archiveUiCards(){return storyArchiveCards().map(c=>normalizeStoryArchiveCardV1?normalizeStoryArchiveCardV1(c):normalizeStoryArchiveCard(c))}
function archiveUiFilterState(){return {q:($('#archiveSearch')?.value||'').toLowerCase().trim(),type:$('#archiveTypeFilter')?.value||'',official:!!$('#archiveOnlyOfficial')?.checked,images:!!$('#archiveOnlyImages')?.checked,vidu:!!$('#archiveOnlyVidu')?.checked}}
function archiveUiMatches(card,f){const imgs=card.images||[],rep=archiveRepresentativeImage(card),hay=[card.title,card.category,card.status,card.body,(card.tags||[]).join(' '),archiveRelatedIds(card).map(id=>getStoryArchiveCard(id)?.title||id).join(' ')].join(' ').toLowerCase();return (!f.q||hay.includes(f.q))&&(!f.type||(f.type==='その他'?!ARCHIVE_UI_TYPES.slice(0,-1).includes(card.category):card.category===f.type))&&(!f.official||card.isConfirmed||card.status==='確定'||imgs.some(i=>i.isOfficial||i.state==='正式採用'))&&(!f.images||!!rep)&&(!f.vidu||imgs.some(i=>i.isViduReference))}
function archiveUiFilters(cards){const f=archiveUiFilterState(),counts=[['',cards.length],...ARCHIVE_UI_TYPES.map(t=>[t,cards.filter(c=>t==='その他'?!ARCHIVE_UI_TYPES.slice(0,-1).includes(c.category):c.category===t).length])];return `<aside class="archive-filter-panel" id="archiveFilters" aria-label="Story Archive filters"><h2>カテゴリ</h2><div class="archive-type-list">${counts.map(([t,n])=>`<button class="${f.type===t?'active':''}" onclick="document.getElementById('archiveTypeFilter').value='${esc(t)}';render()">${esc(t||'すべて')}<span>${n}</span></button>`).join('')}</div><input id="archiveTypeFilter" type="hidden" value="${esc(f.type)}"><div class="archive-filter-more"><h3>さらに</h3><label class="check-row"><input id="archiveOnlyOfficial" type="checkbox" ${f.official?'checked':''} onchange="render()">正式採用のみ</label><label class="check-row"><input id="archiveOnlyVidu" type="checkbox" ${f.vidu?'checked':''} onchange="render()">Vidu参照のみ</label><label class="check-row"><input id="archiveOnlyImages" type="checkbox" ${f.images?'checked':''} onchange="render()">画像ありのみ</label></div></aside>`}
function archiveCardTile(card){return `<article class="archive-board-card" role="button" tabindex="0" onclick="openStoryArchiveDetail('${card.id}')" onkeydown="if(event.key==='Enter'||event.key===' ')openStoryArchiveDetail('${card.id}')"><div class="archive-board-image">${archiveCardListImage(card)}</div><div class="archive-board-body"><h3>${esc(card.title||'無題')}</h3><div class="archive-board-tags"><span>${esc(card.category||'その他')}</span><span>${card.isConfirmed||card.status==='確定'?'正式採用':'検討中'}</span></div><dl><dt>種類</dt><dd>${esc(card.category||'その他')}</dd><dt>画像枚数</dt><dd>${(card.images||[]).length}枚</dd><dt>正式採用</dt><dd>${card.isConfirmed||card.status==='確定'?'はい':'未採用'}</dd></dl></div></article>`}
storyArchiveView=function(){const p=currentProject(),cards=archiveUiCards(),f=archiveUiFilterState(),filtered=cards.filter(c=>archiveUiMatches(c,f));return `<section class="archive-shell"><div class="archive-topbar"><button class="secondary archive-back" onclick="novaReturnHome()">← Nova Studioへ戻る</button><div class="archive-title-block"><p class="eyebrow">Story Archive</p><h1>Story Archive</h1><p class="meta">現在の作品：${esc(p?.title||'未選択')} / 表示 ${filtered.length}件（全${cards.length}件）</p></div><input id="archiveSearch" class="archive-search" placeholder="カード名・本文・タグ・関連カードを検索" value="${esc($('#archiveSearch')?.value||'')}" oninput="render()"><button class="primary-action" onclick="editStoryArchiveCard()">＋ 新しいカード</button><button class="archive-filter-toggle secondary" onclick="document.body.classList.toggle('archive-filters-open')">フィルター</button></div><div class="archive-workspace">${archiveUiFilters(cards)}<section class="archive-grid-panel"><div class="archive-board-grid">${filtered.map(archiveCardTile).join('')||'<p class="empty-note">条件に合うカードはありません。</p>'}</div></section></div></section>`}
function archiveSetRepresentative(cardId,imgId){const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId));card.images=(card.images||[]).map((img,i)=>normalizeArchiveImage({...img,isOfficial:img.id===imgId?true:img.isOfficial,sortOrder:img.id===imgId?0:(+img.sortOrder||i+1)+1},card));saveNormalizedArchiveCard(card);saveState(true);openStoryArchiveDetail(cardId);toast('代表画像に設定しました')}
function archiveToggleImageFlag(cardId,imgId,field){const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId)),img=(card.images||[]).find(i=>i.id===imgId);if(!img)return;img[field]=!img[field];img.updatedAt=now();saveNormalizedArchiveCard(card);saveState(true);openStoryArchiveDetail(cardId);toast(`${field==='isOfficial'?'正式採用':'Vidu参照'}を更新しました`)}
function moveArchiveImage(cardId,imgId,dir){const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId)),imgs=[...(card.images||[])].sort((a,b)=>(+a.sortOrder||0)-(+b.sortOrder||0));const i=imgs.findIndex(x=>x.id===imgId),j=i+dir;if(i<0||j<0||j>=imgs.length)return;[imgs[i],imgs[j]]=[imgs[j],imgs[i]];imgs.forEach((x,n)=>{x.sortOrder=n+1;x.updatedAt=now()});card.images=imgs;saveNormalizedArchiveCard(card);saveState(true);openStoryArchiveDetail(cardId);toast('画像順を変更しました')}
deleteArchiveImage=function(cardId,imgId){if(!confirm('画像の登録情報を削除しますか？画像ファイル本体は削除されません。'))return;const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId));card.images=(card.images||[]).filter(i=>i.id!==imgId);card.imageSets=(card.imageSets||[]).map(s=>({...s,imageIds:(s.imageIds||[]).filter(id=>id!==imgId),baseImageId:s.baseImageId===imgId?'':s.baseImageId}));saveNormalizedArchiveCard(card);saveState(true);openStoryArchiveDetail(cardId);toast('画像登録情報を削除しました')}
archiveImageCard=function(card,img){return `<article class="archive-image-card archive-image-row" onclick="openArchiveImageDetail('${card.id}','${img.id}')">${archiveThumbWithLabels(img)}<div><b>${esc(img.name||'画像資料')}</b>${archiveImageMetaGrid(img)}<small>${archiveImageBadges(img)}</small></div><div class="archive-card-actions"><button onclick="event.stopPropagation();archiveSetRepresentative('${card.id}','${img.id}')">代表画像に設定</button><button onclick="event.stopPropagation();archiveToggleImageFlag('${card.id}','${img.id}','isOfficial')">正式採用${img.isOfficial?'OFF':'ON'}</button><button onclick="event.stopPropagation();archiveToggleImageFlag('${card.id}','${img.id}','isViduReference')">Vidu参照${img.isViduReference?'OFF':'ON'}</button><button onclick="event.stopPropagation();moveArchiveImage('${card.id}','${img.id}',-1)">↑</button><button onclick="event.stopPropagation();moveArchiveImage('${card.id}','${img.id}',1)">↓</button><button onclick="event.stopPropagation();editArchiveImage('${card.id}','${img.id}')">編集</button><button class="danger" onclick="event.stopPropagation();deleteArchiveImage('${card.id}','${img.id}')">削除</button></div></article>`}
openStoryArchiveDetail=function(id,mode='all'){const card=normalizeStoryArchiveCardV1?normalizeStoryArchiveCardV1(getStoryArchiveCard(id)):normalizeStoryArchiveCard(getStoryArchiveCard(id));if(!card)return;modal(`<article class="archive-detail"><h2>${esc(card.title)}</h2>${archiveRepresentativeHero(card)}<section class="archive-gallery-panel"><div class="section-head"><div><h3>画像ギャラリー</h3><p class="meta">画像名・種類・角度・正式採用・Vidu参照を確認できます。</p></div><div class="archive-image-actions"><button class="primary-action" onclick="editArchiveImage('${card.id}')">画像追加</button><button class="secondary" onclick="editArchiveImageSet('${card.id}')">画像セット管理</button></div></div><div class="gallery-tabs">${archiveGalleryTabs(id)}</div>${mode==='set'?'':archiveImageControls(card,mode)}<div id="archiveImageResults_${card.id}">${['type','angle','state'].includes(mode)?archiveGroupedGallery(card,mode):archiveImageGallery(card,mode)}</div>${archiveImageDropZone(card.id)}</section><section><h3>基本設定</h3>${archiveV1TemplateForm({ ...card, templateData: card.templateData||{} }).replaceAll('<textarea','<textarea readonly')}</section><section><h3>本文</h3><p>${esc(card.body||'本文は未入力です。')}</p></section><section><h3>関連カード</h3>${archiveRelatedLinks(card)}</section>${archiveManagementDetails(card)}<button onclick="editStoryArchiveCard('${id}')">カード編集</button><button class="secondary" onclick="closeModal()">閉じる</button></article>`) }
openArchiveImageDetail=function(cardId,imgId){const card=normalizeStoryArchiveCard(getStoryArchiveCard(cardId)),imgs=(card.images||[]).sort((a,b)=>(+a.sortOrder||0)-(+b.sortOrder||0));let idx=imgs.findIndex(i=>i.id===imgId);if(idx<0)return;const img=imgs[idx],prev=imgs[(idx-1+imgs.length)%imgs.length],next=imgs[(idx+1)%imgs.length];archiveLightboxContext={cardId,imgId,prevId:prev?.id,nextId:next?.id};modal(`<div class="archive-lightbox"><button class="archive-lightbox-x" onclick="openStoryArchiveDetail('${cardId}')">×</button><div class="archive-lightbox-stage"><button ${imgs.length<2?'disabled':''} onclick="openArchiveImageDetail('${cardId}','${prev.id}')">‹</button><div class="archive-zoom-target" id="archiveZoomTarget" style="--zoom:1">${archiveThumbWithLabels(img)}</div><button ${imgs.length<2?'disabled':''} onclick="openArchiveImageDetail('${cardId}','${next.id}')">›</button></div><footer class="archive-lightbox-info"><b>${esc(img.name||'画像資料')}</b>${archiveImageMetaGrid(img)}</footer></div>`)}
document.addEventListener('keydown',e=>{if(!archiveLightboxContext||$('#modal')?.classList.contains('hidden'))return;if(e.key==='ArrowLeft')openArchiveImageDetail(archiveLightboxContext.cardId,archiveLightboxContext.prevId);if(e.key==='ArrowRight')openArchiveImageDetail(archiveLightboxContext.cardId,archiveLightboxContext.nextId);if(e.key==='Escape'){const cardId=archiveLightboxContext.cardId;archiveLightboxContext=null;openStoryArchiveDetail(cardId)}});
render();

/* Story Archive 1.4 home-unified archive workspace */
function archiveHomeTypeOptions(cards){const cats=[...new Set([...ARCHIVE_UI_TYPES,...cards.map(c=>c.category||'その他')])].filter(Boolean);return cats.map(cat=>`<option value="${esc(cat)}" ${archiveUiFilterState().type===cat?'selected':''}>${esc(cat)}</option>`).join('')}
function archiveHomeFilters(cards,filtered){const f=archiveUiFilterState();return `<section class="home-panel archive-home-filters"><div class="section-head"><div><p class="eyebrow">Search & Filter</p><h2>検索・フィルター</h2><p class="meta">ホーム画面と同じカードUIで、設定資料をすばやく絞り込みます。</p></div><button class="secondary" onclick="document.getElementById('archiveSearch').value='';document.getElementById('archiveTypeFilter').value='';document.getElementById('archiveOnlyOfficial').checked=false;document.getElementById('archiveOnlyVidu').checked=false;document.getElementById('archiveOnlyImages').checked=false;render()">条件をクリア</button></div><div class="archive-home-filter-grid"><label>キーワード<input id="archiveSearch" placeholder="カード名・本文・タグ・関連カードを検索" value="${esc($('#archiveSearch')?.value||'')}" oninput="render()"></label><label>カテゴリ<select id="archiveTypeFilter" onchange="render()"><option value="">すべて</option>${archiveHomeTypeOptions(cards)}</select></label><label class="check-row"><input id="archiveOnlyOfficial" type="checkbox" ${f.official?'checked':''} onchange="render()">正式採用のみ</label><label class="check-row"><input id="archiveOnlyVidu" type="checkbox" ${f.vidu?'checked':''} onchange="render()">Vidu参照のみ</label><label class="check-row"><input id="archiveOnlyImages" type="checkbox" ${f.images?'checked':''} onchange="render()">画像ありのみ</label></div><div class="stats"><div><b>表示中</b><span>${filtered.length}件</span></div><div><b>全カード</b><span>${cards.length}件</span></div><div><b>画像あり</b><span>${cards.filter(c=>archiveRepresentativeImage(c)).length}件</span></div><div><b>正式採用</b><span>${cards.filter(c=>c.isConfirmed||c.status==='確定'||(c.images||[]).some(i=>i.isOfficial||i.state==='正式採用')).length}件</span></div></div></section>`}
function archiveHomeCardTile(card){const confirmed=card.isConfirmed||card.status==='確定',rep=archiveRepresentativeImage(card);return `<article class="app-card archive-home-card" role="button" tabindex="0" onclick="openStoryArchiveDetail('${card.id}')" onkeydown="if(event.key==='Enter'||event.key===' ')openStoryArchiveDetail('${card.id}')"><div class="app-card-top"><span class="app-icon">${rep?'🖼️':'📚'}</span><span class="ver">${esc(card.category||'その他')}</span></div><div class="archive-home-thumb">${archiveCardListImage(card)}</div><h3>${esc(card.title||'無題')}</h3><p class="meta">${esc(card.body||'本文は未入力です。').slice(0,90)}</p><dl><dt>画像</dt><dd>${(card.images||[]).length}枚</dd><dt>状態</dt><dd>${confirmed?'正式採用':'検討中'}</dd><dt>タグ</dt><dd>${esc((card.tags||[]).slice(0,3).join(', ')||'なし')}</dd></dl><div class="app-actions"><button class="primary-action" onclick="event.stopPropagation();openStoryArchiveDetail('${card.id}')">詳細</button><button class="secondary" onclick="event.stopPropagation();editStoryArchiveCard('${card.id}')">編集</button></div></article>`}
storyArchiveView=function(){const p=currentProject(),cards=archiveUiCards(),f=archiveUiFilterState(),filtered=cards.filter(c=>archiveUiMatches(c,f));return `<section class="home-hero archive-home-hero"><div class="nova-logo"><span class="nova-mark">📚</span><span><b>Story Archive</b><small>設定資料・画像資料</small></span></div><div><p class="eyebrow">Archive Workspace</p><h1>Story Archive</h1><p class="catch">ホーム画面と同じパネル、カード、アクション配置で一覧・詳細・検索・フィルターを統一しました。</p><p class="meta">現在の作品：${esc(p?.title||'未選択')} / 表示 ${filtered.length}件（全${cards.length}件）</p><div class="archive-hero-actions"><button class="primary-action" onclick="editStoryArchiveCard()">＋ 新しいカード</button><button class="secondary" onclick="openMemorySync()">Memory Sync</button><button class="secondary vidu-one-tap" onclick="openArchiveViduReferences()">Vidu参照画像（${archiveViduReferenceImages().length}）</button></div></div></section>${archiveHomeFilters(cards,filtered)}<section class="home-panel"><div class="section-head"><div><p class="eyebrow">Cards</p><h2>アーカイブ一覧</h2></div></div><div class="app-grid archive-home-grid">${filtered.map(archiveHomeCardTile).join('')||'<p class="empty-note">条件に合うカードはありません。</p>'}</div></section><section class="home-panel"><h2>Memory Sync履歴</h2>${memorySyncHistoryRows()}</section>`}
function archiveHomeDetailSummary(card){return `<section class="home-panel"><div class="section-head"><div><p class="eyebrow">Archive Detail</p><h2>${esc(card.title||'無題')}</h2><p class="meta">${esc(card.category||'その他')} / ${card.isConfirmed||card.status==='確定'?'正式採用':'検討中'} / 画像 ${(card.images||[]).length}枚</p></div><div class="app-actions archive-detail-actions"><button class="primary-action" onclick="editStoryArchiveCard('${card.id}')">カード編集</button><button class="secondary" onclick="closeModal()">閉じる</button></div></div><p>${esc(card.body||'本文は未入力です。')}</p></section>`}
openStoryArchiveDetail=function(id,mode='all'){const card=normalizeStoryArchiveCardV1?normalizeStoryArchiveCardV1(getStoryArchiveCard(id)):normalizeStoryArchiveCard(getStoryArchiveCard(id));if(!card)return;modal(`<article class="archive-detail archive-home-detail">${archiveHomeDetailSummary(card)}${archiveRepresentativeHero(card)}${archiveDetailGallerySection(card,mode)}<section class="home-panel"><h3>基本設定</h3>${archiveV1TemplateForm({ ...card, templateData: card.templateData||{} }).replaceAll('<textarea','<textarea readonly')}</section><section class="home-panel"><h3>関連カード</h3>${archiveRelatedLinks(card)}</section>${archiveManagementDetails(card)}</article>`) }
render();

// Load the isolated LINK-02 to LINK-06 adapter after all existing overrides.
const dreamArchitectCoreScript=document.createElement('script');
dreamArchitectCoreScript.src='./dream-architect-transfer-core.js?v=2.0.0';
dreamArchitectCoreScript.onload=()=>{
 const dreamArchitectLinkScript=document.createElement('script');
 dreamArchitectLinkScript.src='./dream-architect-link.js?v=2.0.0';
 document.body.appendChild(dreamArchitectLinkScript);
};
